from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline GEMM kernel written in a straightforward, readable way.
@proc
def kernel_gemm(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # Scale C by beta.
    for i in seq(0, ni):
        for j in seq(0, nj):
            C[i, j] = beta * C[i, j]

    # GEMM update: C += alpha * A * B
    # Written in i-k-j order so that C and B are traversed in row-major
    # order (j is the innermost loop). We also hoist alpha*A[i,k]
    # outside the j loop to avoid redundant multiplies.
    for i in seq(0, ni):
        for k in seq(0, nk):
            a_val: DATA_TYPE
            a_val = alpha * A[i, k]
            for j in seq(0, nj):
                C[i, j] += a_val * B[k, j]


# -----------------------------
# Scheduling / optimization
# -----------------------------

# We now transform the above kernel using Exo's scheduling primitives.
# The goal is to improve data locality and enable a tight, unrolled
# inner micro-kernel over j.

# Locate the loops in the GEMM update part in the original procedure.
# We only use these cursors for identifying the loops; all scheduling
# primitives perform implicit cursor forwarding as the procedure is
# transformed.
k_loop = kernel_gemm.find_loop("k")       # 'for k in seq(0, nk):' in the update
update_i_loop = k_loop.parent()          # the surrounding 'for i in seq(0, ni):'
j_loop = k_loop.body().find_loop("j")    # inner 'for j in seq(0, nj):'

# 1) Reorder the (i, k) loops so that k becomes outermost:
#    for k in ...
#      for i in ...
# This improves reuse of the B[k, :] row across all rows of A and C
# for a fixed k, which is beneficial for cache locality.
kernel_gemm_opt = reorder_loops(kernel_gemm, update_i_loop)

# 2) Tile (block) the j loop inside the GEMM update. We create an
#    outer tile loop 'jo' and an inner loop 'ji' of fixed size.
#    This improves spatial locality when streaming through C[i, j]
#    and B[k, j]. The 'guard' tail strategy ensures correctness for
#    problem sizes that are not multiples of the tile size.
J_TILE = 32
kernel_gemm_opt = divide_loop(kernel_gemm_opt, j_loop, J_TILE, ("jo", "ji"), tail="guard")

# 3) Fully unroll the inner ji loop so that the compiler can keep a
#    small strip of C and B elements in registers and more easily
#    auto-vectorize the resulting straight-line code.
kernel_gemm_opt = unroll_loop(kernel_gemm_opt, "ji")

# 4) Simplify the resulting code: propagate constants, remove
#    redundant control flow, and generally clean up after the
#    transformations above.
kernel_gemm = simplify(kernel_gemm_opt)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
